/**
 * `top_news_stream[]` -- tap "Read the analysis" to expand and reveal `forward_implication` +
 * `transmission_mechanism`. Expansion state is keyed by `url` (per `StockDetailUiState`'s doc), so
 * an item with no `url` can't be expanded -- its row renders without the expand affordance rather
 * than toggling state that has no stable id to key on.
 */
@Composable
fun DirectNews(
    newsStream: List<DomainStockNewsItem>?,
    expandedNewsIds: Set<String>,
    onToggleNews: (String) -> Unit,
    modifier: Modifier = Modifier
) {
    val items = newsStream.orEmpty()
    if (items.isEmpty()) return

    Column(modifier = modifier.fillMaxWidth()) {
        SectionDividerLabel(title = stringResource(id = R.string.stock_detail_direct_news_title))
        Spacer()
        Column(verticalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_medium))) {
            items.forEach { item ->
                NewsCard(
                    item = item,
                    isExpanded = item.url != null && expandedNewsIds.contains(item.url),
                    onToggle = { item.url?.let(onToggleNews) }
                )
            }
        }
    }
}

@Composable
private fun NewsCard(item: DomainStockNewsItem, isExpanded: Boolean, onToggle: () -> Unit) {
    val pulseColors = LocalPulseColors.current

    PulseCard(style = PulseCardStyle.SYNTHESIS, modifier = Modifier.fillMaxWidth().animateContentSize()) {
        Column(modifier = Modifier.padding(dimensionResource(id = R.dimen.padding_large))) {
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                item.impactMagnitude?.let {
                    val (pillColor, textColor) = impactSeverityColors(it, pulseColors)
                    SignalPill(
                        text = stringResource(id = R.string.stock_detail_impact_suffix, it.uppercase(Locale.US)),
                        pillColor = pillColor,
                        contentColor = textColor
                    )
                }
                item.sourceDate?.let {
                    Text(text = it.toLongDateString(), style = MaterialTheme.typography.labelSmall, color = pulseColors.onSurfaceMuted)
                }
            }

            item.headline?.let {
                Spacer()
                Text(
                    text = it,
                    style = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.Bold),
                    color = MaterialTheme.colorScheme.onSurface
                )
            }

            item.articleSynthesis?.let {
                Spacer()
                Text(text = it, style = MaterialTheme.typography.bodyMedium, color = pulseColors.onSurfaceMuted)
            }

            if (isExpanded) {
                item.forwardImplication?.let {
                    Spacer()
                    Text(
                        text = stringResource(id = R.string.stock_detail_forward_implication_label),
                        style = MaterialTheme.typography.labelSmall,
                        color = pulseColors.onSurfaceMuted
                    )
                    Text(text = it, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface)
                }
                item.transmissionMechanism?.let {
                    Spacer()
                    Text(
                        text = stringResource(id = R.string.stock_detail_transmission_mechanism_label),
                        style = MaterialTheme.typography.labelSmall,
                        color = pulseColors.onSurfaceMuted
                    )
                    Text(text = it, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface)
                }
            }

            if (item.url != null) {
                Spacer()
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier.clickable(onClick = onToggle)
                ) {
                    Text(
                        text = stringResource(id = R.string.stock_detail_read_the_analysis),
                        style = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.Bold),
                        color = pulseColors.accentPrimary
                    )
                    Icon(
                        painter = painterResource(id = if (isExpanded) R.drawable.ic_arrow_up else R.drawable.ic_arrow_down),
                        contentDescription = null,
                        tint = pulseColors.accentPrimary,
                        modifier = Modifier.padding(start = dimensionResource(id = R.dimen.padding_small))
                    )
                }
            }
        }
    }
}

@Composable
private fun Spacer() {
    androidx.compose.foundation.layout.Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
}

/**
 * Severity marker for the impact badge -- HIGH impact reads as attention-grabbing (bearish/red,
 * same as WatchList's HIGH urgency treatment), MEDIUM as a caution tone (warning/amber), LOW as
 * muted/neutral. This is a severity read, not a bullish/bearish direction -- `impactMagnitude`
 * says how much a story matters, not whether it's good or bad news for the stock.
 */
private fun impactSeverityColors(impactMagnitude: String, pulseColors: com.marketlabs.pulse.ui.theme.PulseColors): Pair<androidx.compose.ui.graphics.Color, androidx.compose.ui.graphics.Color> =
    when (impactMagnitude.uppercase(Locale.US)) {
        "HIGH" -> pulseColors.signalBearishPill to pulseColors.signalBearishText
        "MEDIUM" -> pulseColors.signalWarningPill to pulseColors.signalWarningText
        else -> pulseColors.signalNeutralPill to pulseColors.signalNeutralText
    }

